// Rovara Code's REAL answers for answering Understand's questions from the Work list and Home (Code #1057: `round` and `outcome` on each `GET /v1/dev/tasks?detail=1` row, and
// `POST /v1/dev/tasks/{id}/answers`), read from code-inline-understand.json. That file was generated by running Code's own handlers in a fresh clone of #1057's tree (its `_about`
// says how); a Cloud test that reads it fails when Cloud drifts from what Code really sends. Regenerate from Code's code when Code changes a shape; never edit a value to make a Cloud test pass.
import { readFileSync } from "node:fs";

type Obj = Record<string, unknown>;
/** One answer as Code's route gave it: its status and JSON body. */
export interface Answer { status: number; body: Obj }

export interface InlineUnderstandFixture {
  _about: string;
  /** The core task MAYA owns, the workflow revision and Understand round its waiting row names, and the request id her accepted answers carried. */
  taskId: string; revision: number; round: number; requestId: string;
  waitingList: Answer; answeredList: Answer; accepted: Answer; staleAnswer: Answer; wrongRound: Answer;
  otherCompanyList: Answer; otherCompanyAnswer: Answer;
  closedTaskId: string; closedList: Answer;
  noAccessTaskId: string; noAccessList: Answer; noAccessAnswer: Answer;
}

export const INLINE_UNDERSTAND = JSON.parse(readFileSync(new URL("./code-inline-understand.json", import.meta.url), "utf8")) as InlineUnderstandFixture;
